// Generated from src/registry/sources/control-ui/recipes/context.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const contextKnobs = [
  "--cui-context-graph-radius",
  "--cui-context-track-fill",
  "--cui-context-segment-tool-fill",
  "--cui-context-segment-message-fill",
  "--cui-context-segment-source-fill",
  "--cui-context-segment-reasoning-fill",
  "--cui-context-overage-fill",
  "--cui-context-limit-marker-color",
] as const;
export type ContextKnobStyle = Partial<Record<(typeof contextKnobs)[number], string>>;

import type { ReactNode } from "react";

export type ContextSegmentKind = "system" | "tool" | "message" | "source" | "reasoning" | "cache" | "other";

export type ContextStatus = "normal" | "over-limit" | "unavailable";

export type ContextSegment = {
  id: string;
  label: string;
  tokens: number;
  kind?: ContextSegmentKind;
  description?: ReactNode;
};

export type ContextModelSegment = {
  segment: ContextSegment;
  kind: ContextSegmentKind;
  tokens: number;
  start: number;
  width: number;
  ratio: number | null;
};

export type ContextModel = {
  segments: readonly ContextModelSegment[];
  usedTokens: number;
  maxTokens: number | null;
  remainingTokens: number | null;
  overageTokens: number;
  ratio: number | null;
  domain: number;
  limitPosition: number | null;
  status: ContextStatus;
};

function deriveContextModelSegments(segments: readonly ContextSegment[], domain: number, validLimit: number | null): ContextModelSegment[] {
  let consumedTokens = 0;
  return segments.map((segment) => {
    const tokens = Number.isFinite(segment.tokens) && segment.tokens > 0 ? segment.tokens : 0;
    const modelSegment = {
      segment,
      kind: segment.kind ?? "other",
      tokens,
      start: (consumedTokens / domain) * 100,
      width: (tokens / domain) * 100,
      ratio: validLimit === null ? null : tokens / validLimit,
    } satisfies ContextModelSegment;
    consumedTokens += tokens;
    return modelSegment;
  });
}

function deriveValidatedUsedTokens(segments: readonly ContextSegment[]): number {
  const ids = new Set<string>();
  let usedTokens = 0;
  for (const segment of segments) {
    if (ids.has(segment.id)) throw new Error(`Context segment ids must be unique: "${segment.id}".`);
    ids.add(segment.id);
    usedTokens += Number.isFinite(segment.tokens) && segment.tokens > 0 ? segment.tokens : 0;
  }
  return usedTokens;
}

export function deriveContextModel(segments: readonly ContextSegment[], maxTokens?: number | null): ContextModel {
  const usedTokens = deriveValidatedUsedTokens(segments);

  const validLimit = Number.isFinite(maxTokens) && (maxTokens ?? 0) > 0 ? (maxTokens ?? null) : null;
  const domain = Math.max(validLimit ?? 0, usedTokens, 1);
  const remainingTokens = validLimit === null ? null : Math.max(0, validLimit - usedTokens);
  const overageTokens = validLimit === null ? 0 : Math.max(0, usedTokens - validLimit);
  const ratio = validLimit === null ? null : usedTokens / validLimit;
  const limitPosition = validLimit === null ? null : (validLimit / domain) * 100;
  let status: ContextStatus = "normal";
  if (validLimit === null) status = "unavailable";
  else if (overageTokens > 0) status = "over-limit";
  const modelSegments = deriveContextModelSegments(segments, domain, validLimit);

  return {
    segments: modelSegments,
    usedTokens,
    maxTokens: validLimit,
    remainingTokens,
    overageTokens,
    ratio,
    domain,
    limitPosition,
    status,
  } satisfies ContextModel;
}

"use client";

import { X } from "lucide-react";
import type { ComponentProps, CSSProperties, ReactNode } from "react";
import { createContext, useContext } from "react";
import type { ContextSegment, ContextSegmentKind } from "@/components/control-ui/context-model";
import type { OpenChangeEventDetails } from "@/components/control-ui/control-props";
import type { ButtonKnobStyle } from "@/components/control-ui/knob-contracts/button-knobs";
import type { ContextKnobStyle } from "@/components/control-ui/knob-contracts/context-knobs";
import type { PopupKnobStyle } from "@/components/control-ui/knob-contracts/popup-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { Button } from "@/components/control-ui/ui/button";
import {
  Popover,
  PopoverClose,
  PopoverContent,
  PopoverDescription,
  PopoverTitle,
  PopoverTrigger,
} from "@/components/control-ui/ui/popover";
import { ScrollArea } from "@/components/control-ui/ui/scroll-area";
import type { ContextModel } from "./context-model";
import { deriveContextModel } from "./context-model";

export type ContextProps = Omit<ComponentProps<"div">, "children"> & {
  segments: readonly ContextSegment[];
  maxTokens?: number | null;
  model?: string;
  locale?: Intl.LocalesArgument;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean, eventDetails: OpenChangeEventDetails) => void;
  children?: ReactNode;
} & { style?: CSSProperties & ContextKnobStyle };

type ContextStyleProps<Props, Style> = Omit<Props, "style"> & { style?: CSSProperties & Style };

type ContextValue = {
  model: ContextModel;
  modelName: string | undefined;
  numberFormatter: Intl.NumberFormat;
  percentageFormatter: Intl.NumberFormat;
};

const ContextValueContext = createContext<ContextValue | null>(null);

function useContextValue(): ContextValue {
  const context = useContext(ContextValueContext);
  if (!context) throw new Error("Context parts must be rendered inside <Context>.");
  return context;
}

export function Context({
  segments,
  maxTokens,
  model: modelName,
  locale,
  open,
  defaultOpen,
  onOpenChange,
  className,
  children,
  ...props
}: ContextProps) {
  const model = deriveContextModel(segments, maxTokens);
  const context = {
    model,
    modelName,
    numberFormatter: new Intl.NumberFormat(locale),
    percentageFormatter: new Intl.NumberFormat(locale, {
      style: "percent",
      maximumFractionDigits: 1,
    }),
  } satisfies ContextValue;

  return (
    <ContextValueContext.Provider value={context}>
      <div
        {...props}
        data-control-ui="context"
        data-control-family="context"
        data-slot="root"
        data-status={model.status}
        className={cn("inline-flex", className)}
      >
        <Popover open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange}>
          {children ?? (
            <>
              <ContextTrigger />
              <ContextContent />
            </>
          )}
        </Popover>
      </div>
    </ContextValueContext.Provider>
  );
}

export type ContextTriggerProps = ContextStyleProps<ComponentProps<typeof Button>, ButtonKnobStyle & ContextKnobStyle>;

export function ContextTrigger({
  "aria-label": ariaLabel,
  variant = "surface",
  size = "sm",
  className,
  children,
  ...props
}: ContextTriggerProps) {
  const { model, numberFormatter, percentageFormatter } = useContextValue();
  const percentage = model.ratio === null ? null : percentageFormatter.format(model.ratio);
  const visualPercentage = Math.min(100, Math.max(0, (model.ratio ?? 0) * 100));
  const shortLabel = percentage === null ? "Context unavailable" : `${percentage} context`;
  const accessibleLabel =
    model.maxTokens === null
      ? `Context window: ${numberFormatter.format(model.usedTokens)} tokens used; limit unavailable`
      : `Context window: ${numberFormatter.format(model.usedTokens)} of ${numberFormatter.format(model.maxTokens)} tokens used (${percentage})${
          model.overageTokens > 0 ? `; ${numberFormatter.format(model.overageTokens)} tokens over limit` : ""
        }`;

  return (
    <span
      data-control-ui="context"
      data-control-family="context"
      data-slot="trigger"
      data-status={model.status}
      className="relative inline-flex"
    >
      <Button
        data-context-trigger-button="true"
        {...props}
        render={<PopoverTrigger />}
        variant={variant}
        size={size}
        aria-label={ariaLabel ?? accessibleLabel}
        className={cn("group/context after:absolute after:-inset-1.5 after:content-['']", className)}
      >
        {children ?? (
          <>
            <svg
              data-control-ui="context"
              data-control-family="context"
              data-slot="trigger-indicator"
              data-status={model.status}
              viewBox="0 0 16 16"
              aria-hidden="true"
              className="size-4 shrink-0 -rotate-90"
            >
              <circle
                cx="8"
                cy="8"
                r="6.25"
                strokeWidth="1.5"
                data-control-ui="context"
                data-control-family="context"
                data-slot="trigger-track"
                data-status={model.status}
              />
              {model.status !== "unavailable" ? (
                <circle
                  cx="8"
                  cy="8"
                  r="6.25"
                  pathLength="100"
                  strokeDasharray={`${visualPercentage} 100`}
                  strokeLinecap="round"
                  strokeWidth="1.5"
                  data-control-ui="context"
                  data-control-family="context"
                  data-slot="trigger-value"
                  data-status={model.status}
                />
              ) : null}
            </svg>
            <span
              data-control-ui="context"
              data-control-family="context"
              data-slot="trigger-label"
              className="max-w-0 overflow-hidden group-hover/context:max-w-32 group-focus-visible/context:max-w-32 group-data-[popup-open]/context:max-w-32"
            >
              {shortLabel}
            </span>
          </>
        )}
      </Button>
    </span>
  );
}

export type ContextContentProps = ContextStyleProps<ComponentProps<typeof PopoverContent>, PopupKnobStyle & ContextKnobStyle>;

export function ContextContent({
  "aria-label": ariaLabel,
  side = "top",
  align = "end",
  sideOffset = 8,
  collisionPadding = 16,
  padding = "none",
  className,
  children,
  ...props
}: ContextContentProps) {
  const { modelName } = useContextValue();

  return (
    <PopoverContent
      {...props}
      // default panel carries no title, so popup needs name of its own
      aria-label={ariaLabel ?? (modelName ? `Context window · ${modelName}` : "Context window")}
      side={side}
      align={align}
      sideOffset={sideOffset}
      collisionPadding={collisionPadding}
      padding={padding}
      className={cn("w-[min(28rem,calc(100vw-2rem))] overflow-hidden", className)}
    >
      <div data-control-ui="context" data-control-family="context" data-slot="content" className="overflow-hidden">
        {children ?? (
          <ScrollArea maxHeight="min(36rem, calc(100dvh - 8rem))" lockAxis="x">
            <div className="grid gap-4 p-4">
              <ContextSummary />
              <ContextGraph />
              <ContextLegend />
            </div>
          </ScrollArea>
        )}
      </div>
    </PopoverContent>
  );
}

export type ContextHeaderProps = ComponentProps<"div"> & { style?: CSSProperties & ContextKnobStyle };

export function ContextHeader({ className, children, ...props }: ContextHeaderProps) {
  return (
    <div
      {...props}
      data-control-ui="context"
      data-control-family="context"
      data-slot="header"
      className={cn("flex items-start gap-3 p-4 pb-0", className)}
    >
      {children ?? (
        <>
          <div className="min-w-0 flex-1">
            <ContextTitle />
            <ContextDescription />
          </div>
          <ContextClose />
        </>
      )}
    </div>
  );
}

export type ContextTitleProps = ContextStyleProps<ComponentProps<typeof PopoverTitle>, ContextKnobStyle>;

export function ContextTitle({ className, children, ...props }: ContextTitleProps) {
  return (
    <PopoverTitle {...props} data-control-ui="context" data-control-family="context" data-slot="title" className={className}>
      {children ?? "Context window"}
    </PopoverTitle>
  );
}

export type ContextDescriptionProps = ContextStyleProps<ComponentProps<typeof PopoverDescription>, ContextKnobStyle>;

export function ContextDescription({ className, children, ...props }: ContextDescriptionProps) {
  const { modelName } = useContextValue();
  return (
    <PopoverDescription {...props} data-control-ui="context" data-control-family="context" data-slot="description" className={className}>
      {children ?? modelName ?? "Token usage by context segment"}
    </PopoverDescription>
  );
}

export type ContextSummaryProps = ContextStyleProps<ComponentProps<"div">, ContextKnobStyle>;

export function ContextSummary({ className, children, ...props }: ContextSummaryProps) {
  const { model, numberFormatter, percentageFormatter } = useContextValue();
  const percentage = model.ratio === null ? null : percentageFormatter.format(model.ratio);

  return (
    <div
      {...props}
      data-control-ui="context"
      data-control-family="context"
      data-slot="summary"
      data-status={model.status}
      className={cn("flex items-baseline justify-between gap-3", className)}
    >
      {children ?? (
        <>
          <span>{percentage === null ? `${numberFormatter.format(model.usedTokens)} tokens used` : `${percentage} used`}</span>
          <span data-control-ui="context" data-control-family="context" data-slot="summary-value">
            {model.maxTokens === null
              ? "Limit unavailable"
              : `${numberFormatter.format(model.usedTokens)} / ${numberFormatter.format(model.maxTokens)} tokens`}
          </span>
        </>
      )}
    </div>
  );
}

export type ContextGraphProps = ContextStyleProps<Omit<ComponentProps<"svg">, "children">, ContextKnobStyle>;

export function ContextGraph({ className, ...props }: ContextGraphProps) {
  const { model } = useContextValue();

  return (
    <svg
      {...props}
      data-control-ui="context"
      data-control-family="context"
      data-slot="graph"
      data-status={model.status}
      viewBox="0 0 100 10"
      preserveAspectRatio="none"
      aria-hidden="true"
      className={cn("h-2.5 w-full overflow-hidden", className)}
    >
      <rect data-control-ui="context" data-control-family="context" data-slot="track" x="0" y="0" width="100" height="10" rx="5" />
      {model.segments.map((segment) => (
        <rect
          key={segment.segment.id}
          data-control-ui="context"
          data-control-family="context"
          data-slot="segment"
          data-kind={segment.kind}
          x={segment.start}
          y="0"
          width={segment.width}
          height="10"
        />
      ))}
      {model.status === "over-limit" && model.limitPosition !== null ? (
        <>
          <rect
            data-control-ui="context"
            data-control-family="context"
            data-slot="overage"
            x={model.limitPosition}
            y="0"
            width={100 - model.limitPosition}
            height="10"
          />
          <line
            data-control-ui="context"
            data-control-family="context"
            data-slot="limit-marker"
            x1={model.limitPosition}
            x2={model.limitPosition}
            y1="0"
            y2="10"
            vectorEffect="non-scaling-stroke"
          />
        </>
      ) : null}
    </svg>
  );
}

export type ContextLegendProps = ContextStyleProps<ComponentProps<"ul">, ContextKnobStyle>;

type ContextLegendRowProps = {
  kind: ContextSegmentKind;
  label: ReactNode;
  description?: ReactNode;
  value?: ReactNode;
  tone?: "available" | "over-limit";
};

function ContextLegendRow({ kind, label, description, value, tone }: ContextLegendRowProps) {
  return (
    <li
      data-control-ui="context"
      data-control-family="context"
      data-slot="legend-item"
      data-kind={kind}
      data-tone={tone}
      className="grid grid-cols-[minmax(0,1fr)_auto] items-start gap-3 py-1.5"
    >
      <div className="flex min-w-0 items-start gap-2">
        <span
          data-control-ui="context"
          data-control-family="context"
          data-slot="legend-indicator"
          data-kind={kind}
          aria-hidden="true"
          className="mt-1 size-2.5 shrink-0"
        />
        <div className="min-w-0">
          <div data-control-ui="context" data-control-family="context" data-slot="legend-label">
            {label}
          </div>
          {description !== undefined && description !== null ? (
            <div data-control-ui="context" data-control-family="context" data-slot="legend-description">
              {description}
            </div>
          ) : null}
        </div>
      </div>
      {value !== undefined && value !== null ? (
        <span data-control-ui="context" data-control-family="context" data-slot="legend-value">
          {value}
        </span>
      ) : null}
    </li>
  );
}

export function ContextLegend({ className, children, ...props }: ContextLegendProps) {
  const { model, numberFormatter, percentageFormatter } = useContextValue();

  return (
    <ul {...props} data-control-ui="context" data-control-family="context" data-slot="legend" className={cn("grid", className)}>
      {children ?? (
        <>
          {model.segments.map((segment) => (
            <ContextLegendRow
              key={segment.segment.id}
              kind={segment.kind}
              label={segment.segment.label}
              description={segment.segment.description}
              value={`${numberFormatter.format(segment.tokens)} tokens${
                segment.ratio === null ? "" : ` · ${percentageFormatter.format(segment.ratio)}`
              }`}
            />
          ))}
          {model.status === "normal" && model.remainingTokens !== null ? (
            <ContextLegendRow
              kind="other"
              label="Available"
              tone="available"
              value={`${numberFormatter.format(model.remainingTokens)} tokens · ${percentageFormatter.format(
                model.remainingTokens / (model.maxTokens ?? 1),
              )}`}
            />
          ) : null}
          {model.status === "over-limit" ? (
            <ContextLegendRow
              kind="other"
              label="Over limit"
              tone="over-limit"
              value={`${numberFormatter.format(model.overageTokens)} tokens over limit`}
            />
          ) : null}
          {model.status === "unavailable" ? <ContextLegendRow kind="other" label="Limit unavailable" /> : null}
        </>
      )}
    </ul>
  );
}

export type ContextCloseProps = ComponentProps<typeof Button>;

export function ContextClose({
  variant = "ghost",
  size = "xs",
  iconOnly = true,
  "aria-label": ariaLabel = "Close context window",
  className,
  children,
  ...props
}: ContextCloseProps) {
  return (
    <Button
      {...props}
      render={<PopoverClose />}
      variant={variant}
      size={size}
      iconOnly={iconOnly}
      aria-label={ariaLabel}
      className={cn("ml-auto", className)}
    >
      {children ?? <X aria-hidden="true" className="size-4" />}
    </Button>
  );
}

@layer components {
  :where([data-control-family="context"][data-slot="root"], [data-control-family="context"][data-slot="content"]) {
    --cui-context-graph-radius: 9999px;
    --cui-context-limit-marker-color: var(--destructive-text);
    --cui-context-overage-fill: oklch(from var(--destructive-text) l c h / 0.22);
    --cui-context-track-fill: var(--muted);
    --cui-context-segment-message-fill: oklch(from var(--primary) l c h / 0.65);
    --cui-context-segment-reasoning-fill: oklch(from var(--foreground) l c h / 0.5);
    --cui-context-segment-source-fill: oklch(from var(--accent-foreground) l c h / 0.65);
    --cui-context-segment-tool-fill: var(--primary);
  }

  :where([data-control-family="context"][data-slot="trigger-indicator"]) {
    fill: none;
  }

  :where([data-control-family="context"][data-slot="trigger-track"]) {
    stroke: oklch(from var(--border) l c h / 0.7);
  }

  :where([data-control-family="context"][data-slot="trigger-track"][data-status="unavailable"]) {
    stroke: var(--muted);
  }

  :where([data-control-family="context"][data-slot="trigger-value"]) {
    stroke: var(--primary);
  }

  :where([data-control-family="context"][data-slot="trigger-value"][data-status="over-limit"]) {
    stroke: var(--destructive-text);
  }

  :where([data-control-family="context"][data-slot="trigger-label"]) {
    opacity: 0;
    transition-property: max-width, opacity;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where(
    [data-context-trigger-button="true"]:is(:hover, :focus-visible, [data-popup-open])
      [data-control-family="context"][data-slot="trigger-label"]
  ) {
    opacity: 1;
  }

  :where([data-control-family="context"][data-slot="title"]) {
    font-size: var(--text-sm);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="context"][data-slot="description"]) {
    color: var(--muted-foreground);
    font-size: var(--text-caption);
  }

  :where([data-control-family="context"][data-slot="summary"]) {
    font-size: var(--text-sm);
  }

  :where([data-control-family="context"][data-slot="summary-value"]) {
    color: var(--muted-foreground);
    font-variant-numeric: tabular-nums;
  }

  :where([data-control-family="context"][data-slot="graph"]) {
    border-radius: var(--cui-context-graph-radius);
  }

  :where([data-control-family="context"][data-slot="track"]) {
    fill: var(--cui-context-track-fill);
  }

  :where([data-control-family="context"][data-slot="segment"]) {
    fill: var(--border);
  }

  :where([data-control-family="context"][data-slot="segment"][data-kind="system"]) {
    fill: oklch(from var(--foreground) l c h / 0.75);
  }

  :where([data-control-family="context"][data-slot="segment"][data-kind="tool"]) {
    fill: var(--cui-context-segment-tool-fill);
  }

  :where([data-control-family="context"][data-slot="segment"][data-kind="message"]) {
    fill: var(--cui-context-segment-message-fill);
  }

  :where([data-control-family="context"][data-slot="segment"][data-kind="source"]) {
    fill: var(--cui-context-segment-source-fill);
  }

  :where([data-control-family="context"][data-slot="segment"][data-kind="reasoning"]) {
    fill: var(--cui-context-segment-reasoning-fill);
  }

  :where([data-control-family="context"][data-slot="segment"][data-kind="cache"]) {
    fill: oklch(from var(--muted-foreground) l c h / 0.55);
  }

  :where([data-control-family="context"][data-slot="overage"]) {
    fill: var(--cui-context-overage-fill);
  }

  :where([data-control-family="context"][data-slot="limit-marker"]) {
    stroke: var(--cui-context-limit-marker-color);
  }

  :where([data-control-family="context"][data-slot="legend-indicator"]) {
    border-radius: 9999px;
    background: var(--border);
  }

  :where([data-control-family="context"][data-slot="legend-indicator"][data-kind="system"]) {
    background: oklch(from var(--foreground) l c h / 0.75);
  }

  :where([data-control-family="context"][data-slot="legend-indicator"][data-kind="tool"]) {
    background: var(--cui-context-segment-tool-fill);
  }

  :where([data-control-family="context"][data-slot="legend-indicator"][data-kind="message"]) {
    background: var(--cui-context-segment-message-fill);
  }

  :where([data-control-family="context"][data-slot="legend-indicator"][data-kind="source"]) {
    background: var(--cui-context-segment-source-fill);
  }

  :where([data-control-family="context"][data-slot="legend-indicator"][data-kind="reasoning"]) {
    background: var(--cui-context-segment-reasoning-fill);
  }

  :where([data-control-family="context"][data-slot="legend-indicator"][data-kind="cache"]) {
    background: oklch(from var(--muted-foreground) l c h / 0.55);
  }

  :where([data-control-family="context"][data-slot="legend-item"][data-tone="available"] [data-slot="legend-indicator"]) {
    background: var(--muted);
  }

  :where([data-control-family="context"][data-slot="legend-item"][data-tone="over-limit"] [data-slot="legend-indicator"]) {
    background: var(--destructive-text);
  }

  :where([data-control-family="context"][data-slot="legend-label"]) {
    font-size: var(--text-sm);
  }

  :where([data-control-family="context"]:is([data-slot="legend-description"], [data-slot="legend-value"])) {
    color: var(--muted-foreground);
    font-size: var(--text-caption);
  }

  :where([data-control-family="context"][data-slot="legend-value"]) {
    font-variant-numeric: tabular-nums;
  }
}

@property --cui-context-graph-radius {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-context-track-fill {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-context-segment-tool-fill {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

